  effects.push({mesh:bullet,life:weapon==='ROCKET'?0.45:0.22,max:weapon==='ROCKET'?0.45:0.22,bullet:true,explosive:isExplosive,lane:game.lane,damage:info.damage});
  const targets=actors.filter(a=>a.userData.kind==='enemy'||a.userData.kind==='crate').filter(a=>a.userData.lane===game.lane&&a.position.z<-0.35&&a.position.z>-30).sort((a,b)=>b.position.z-a.position.z);
